          </div>

          {/* Мобильное закрытие */}
          <button
            type="button"
            onClick={onCloseMobile}
            className="lg:hidden p-2 -mr-1 rounded-lg text-on-muted hover:text-on-surface hover:bg-surface transition-colors"
