+/* Диагностика локальной БД: сколько категорий/фото и есть ли файлы на диске. */
+const { PrismaClient } = require('@prisma/client');
+const fs = require('fs');
+const path = require('path');
+
+const prisma = new PrismaClient();
+
+(async () => {
+  const categories = await prisma.category.findMany({
+    orderBy: { sortOrder: 'asc' },
+    include: { _count: { select: { photos: true } } },
+  });
+  const photos = await prisma.photo.findMany({ orderBy: { sortOrder: 'asc' } });
+  const uploadsDir = path.join(process.cwd(), 'uploads', 'portfolio');
+
+  console.log(`Категорий: ${categories.length}`);
+  categories.forEach((c) => console.log(`  - ${c.name} (${c.slug}) — ${c._count.photos} фото, sortOrder=${c.sortOrder}`));
+
+  const missing = photos.filter((p) => !fs.existsSync(path.join(uploadsDir, p.filename)));
+  console.log(`Фото в БД: ${photos.length}, нет файла на диске: ${missing.length}`);
+  missing.slice(0, 5).forEach((p) => console.log(`  ! ${p.title} -> ${p.filename}`));
+
+  const unassigned = photos.filter((p) => !p.categoryId).length;
+  console.log(`Фото без категории: ${unassigned}`);
+
+  const users = await prisma.user.findMany({ select: { email: true, role: true } });
+  console.log(`Пользователи: ${users.map((u) => `${u.email} (${u.role})`).join(', ') || 'нет'}`);
+
+  await prisma.$disconnect();
+})().catch(async (e) => {
+  console.error(e);
+  await prisma.$disconnect();
+  process.exit(1);
+});
