+/* Временный smoke-тест: логин админа → загрузка фото → удаление. */
+import fs from 'node:fs';
+import path from 'node:path';
+
+const BASE = 'http://localhost:3001/api';
+const email = 'admin@electromontage.ru';
+const password = 'ElectroAdmin2024!';
+
+const login = await fetch(`${BASE}/auth/login`, {
+  method: 'POST',
+  headers: { 'Content-Type': 'application/json' },
+  body: JSON.stringify({ email, password }),
+});
+
+const rawCookie = login.headers.getSetCookie?.() ?? [];
+const cookie = rawCookie.map((c) => c.split(';')[0]).join('; ');
+console.log('login:', login.status, 'cookies:', rawCookie.length);
+
+const cats = await fetch(`${BASE}/public/categories`).then((r) => r.json());
+const categoryId = cats[0]?.id;
+console.log('categories:', cats.length, 'first:', cats[0]?.name);
