+const imgPath = path.resolve('..', 'frontend', 'src', 'assets', 'portfolio', 'provodka', fs.readdirSync(path.resolve('..', 'frontend', 'src', 'assets', 'portfolio', 'provodka'))[0]);
+const buf = fs.readFileSync(imgPath);
+const form = new FormData();
+form.append('file', new Blob([buf], { type: 'image/webp' }), 'smoke-test.webp');
+form.append('categoryId', categoryId);
+form.append('title', 'Smoke test');
+
+const upload = await fetch(`${BASE}/photos`, { method: 'POST', headers: { cookie }, body: form });
